var t=`1128-shrimp-and-grits`;var n=`world-1128`;var s=`US`;var r=`northern-america`;var a=4;var o=45;var d={en:`Shrimp and Grits`,ua:`Креветки з кукурудзяною кашею`};var g={en:`Shrimp and Grits is a dish from United States prepared with corn grits, whole cow milk, cheddar cheese, shrimp. This is a home-scale version with measured ingredients in the individual steps where they are used.`,ua:`Креветки з кукурудзяною кашею, страва кухні країни Сполучені Штати Америки, яку готують із таких продуктів: кукурудзяна крупа, цільне коров'яче молоко, сир чедер, креветка. Кількості в домашньому рецепті прив’язані до окремих етапів приготування.`};var h=[{en:`Slowly stir the grains into the simmering liquid; cook over low heat for about 26 minutes, stirring to prevent sticking.`,ua:`Повільно всипте крупу в гарячу рідину; варіть на слабкому вогні приблизно 26 хвилин, помішуючи, щоб не пристала до дна.`,t:[`absorption-cooking`],m:26,i:[[`corn-grits`,300,`g`],[`water`,1e3,`ml`],[`whole-cow-milk`,330,`ml`],[`table-salt`,7,`g`]]},{en:`Combine the listed ingredients in a bowl until evenly mixed; avoid overworking delicate components.`,ua:`З’єднайте зазначені складники в мисці до однорідності; не перемішуйте ніжні компоненти надто довго.`,t:[`mixing`],m:5,i:[[`unsalted-butter`,50,`g`],[`cheddar-cheese`,120,`g`]]},{en:`Chop the vegetables as needed. Sauté the listed ingredients over medium heat, stirring, for about 11 minutes until softened and aromatic.`,ua:`Наріжте овочі за потреби. Пасеруйте зазначені складники на середньому вогні, помішуючи, приблизно 11 хвилин до м’якості й аромату.`,t:[`chopping`,`sauteing`],m:11,i:[[`shrimp`,650,`g`],[`bacon`,140,`g`],[`garlic`,4,`clove`],[`smoked-paprika`,6,`g`]]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:3,i:[[`lemon-juice`,30,`ml`],[`green-onion`,35,`g`]]}];var m={slug:t,id:n,country:`US`,region:r,servings:4,minutes:45,title:d,text:g,steps:h};export{s as country,m as default,n as id,o as minutes,r as region,a as servings,t as slug,h as steps,g as text,d as title};